import Configuration
import Foundation
import SystemPackage

/// Recognizes generated sources and macro expansion buffers, which a fix never edits.
enum GeneratedFile {
    /// Whether the path alone marks a generated file.
    static func isGenerated(path: FilePath) -> Bool {
        let name = path.lastComponent?.string ?? ""
        if name == Configuration.generatedAssetSymbolsFileName
            || name.hasPrefix(Configuration.generatedStringSymbolsFileNamePrefix)
            || name.contains("@__swiftmacro_")
            || name.hasSuffix(".generated.swift")
        {
            return true
        }
        return path.components.contains { ["DerivedData", ".build"].contains($0.string) }
    }

    /// Whether the path or the header comment of the file marks it as generated.
    static func isGenerated(path: FilePath, contents: [UInt8]) -> Bool {
        isGenerated(path: path) || hasGeneratedHeader(contents)
    }

    // MARK: - Private

    private static let headerMarkers = ["@generated", "do not edit", "generated by", "generated using", "auto-generated", "autogenerated"]

    /// Looks for a marker in the comment lines at the top of the file.
    private static func hasGeneratedHeader(_ contents: [UInt8]) -> Bool {
        let prefix = contents.prefix(4096)
        let lineEnd = prefix.count < contents.count ? prefix.lastIndex(of: UInt8(ascii: "\n")) ?? 0 : prefix.count
        guard let header = String(bytes: prefix.prefix(lineEnd), encoding: .utf8) else { return false }

        let commentLines = header.split(separator: "\n", omittingEmptySubsequences: false)
            .prefix(30)
            .map { $0.trimmingCharacters(in: .whitespaces) }
            .prefix { $0.isEmpty || $0.hasPrefix("//") || $0.hasPrefix("/*") || $0.hasPrefix("*") }

        return commentLines.contains { line in
            let lowercased = line.lowercased()
            return headerMarkers.contains { lowercased.contains($0) }
        }
    }
}
